CREATE OR REPLACE FUNCTION public.auto_hide_after_reports()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_distinct_reporters int;
begin
  select count(distinct reporter_id) into v_distinct_reporters
  from reports
  where reported_id = new.reported_id;

  if v_distinct_reporters >= 3 then
    update profiles set is_hidden = true where id = new.reported_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_daily_views_state(p_user uuid)
 RETURNS TABLE(daily_views_count integer, daily_views_reset_at timestamp with time zone, is_premium boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count int;
  v_reset timestamptz;
  v_premium boolean;
begin
  if auth.uid() is distinct from p_user then
    raise exception 'not authorized';
  end if;

  select p.daily_views_count, p.daily_views_reset_at, coalesce(p.is_premium, false)
    into v_count, v_reset, v_premium
    from profiles p
    where p.id = p_user
    for update;

  if v_count is null then
    v_count := 0;
  end if;

  if v_reset is null or v_reset + interval '24 hours' < now() then
    v_count := 0;
    v_reset := now();
    update profiles
      set daily_views_count = v_count,
          daily_views_reset_at = v_reset
      where id = p_user;
  end if;

  return query select v_count, v_reset, v_premium;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_mutual_accept()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.user_a_accepted = true and new.user_b_accepted = true then
    new.status := 'accepted';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.increment_daily_views(p_user uuid)
 RETURNS TABLE(daily_views_count integer, daily_views_reset_at timestamp with time zone, is_premium boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
  v_reset timestamptz;
  v_premium boolean;
begin
  IF auth.uid() IS DISTINCT FROM p_user THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  select p.daily_views_count, p.daily_views_reset_at, coalesce(p.is_premium, false)
    into v_count, v_reset, v_premium
    from profiles p
    where p.id = p_user
    for update;

  if v_count is null then
    v_count := 0;
  end if;

  if v_reset is null or v_reset + interval '24 hours' < now() then
    v_count := 0;
    v_reset := now();
  end if;

  v_count := v_count + 1;

  update profiles
    set daily_views_count = v_count,
        daily_views_reset_at = v_reset
    where id = p_user;

  return query select v_count, v_reset, v_premium;
end;
$function$

CREATE OR REPLACE FUNCTION public.try_send_invite(p_user uuid, p_is_premium boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_limit int; v_count int; v_reset timestamptz; v_is_premium boolean;
BEGIN
  IF auth.uid() IS DISTINCT FROM p_user THEN
    RETURN false;
  END IF;

  SELECT daily_invites_count, daily_invites_reset_at, COALESCE(is_premium, false)
    INTO v_count, v_reset, v_is_premium
    FROM profiles WHERE id = p_user
    FOR UPDATE;

  IF v_count IS NULL THEN
    RETURN false;               -- profil bulunamadı
  END IF;

  IF v_reset IS NULL OR v_reset < now() - interval '24 hours' THEN
    v_count := 0;                -- 24 saat geçmiş, sıfırla
    UPDATE profiles SET daily_invites_reset_at = now() WHERE id = p_user;
  END IF;

  v_limit := CASE WHEN v_is_premium THEN 3 ELSE 1 END;

  IF v_count >= v_limit THEN
    RETURN false;                -- limit dolu
  END IF;

  UPDATE profiles SET daily_invites_count = v_count + 1 WHERE id = p_user;
  RETURN true;                   -- davet hakkı verildi
END;
$function$

CREATE OR REPLACE FUNCTION public.update_match_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.user_a_accepted = true AND NEW.user_b_accepted = true THEN
    NEW.status := 'accepted';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
